package net.civeira.phylax.feature.observe.observedissuecomment.application.usecase.create;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueReference;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.ObservedIssueCommentChangeSet;

class ObservedIssueCommentCreateInputUnitTest {

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the observed issue comment input values are kept when converted to a change set and back")
  void test_observed_issue_comment_create_input_change_set_round_trip() {
    ObservedIssueCommentCreateInput input =
        ObservedIssueCommentCreateInput.builder().uid("one").issue(ObservedIssueReference.of("one"))
            .author("one").authorName("one").text("one").createdAt(LocalDateTime
                .of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime())
            .version(1).build();
    ObservedIssueCommentChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    ObservedIssueCommentCreateInput copy = ObservedIssueCommentCreateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getIssue().isPresent(), "issue must be assigned by the builder");
    Assertions.assertEquals(input.getIssue(), copy.getIssue(),
        "issue must survive the change set round trip");
    Assertions.assertTrue(input.getAuthor().isPresent(), "author must be assigned by the builder");
    Assertions.assertEquals(input.getAuthor(), copy.getAuthor(),
        "author must survive the change set round trip");
    Assertions.assertTrue(input.getAuthorName().isPresent(),
        "authorName must be assigned by the builder");
    Assertions.assertEquals(input.getAuthorName(), copy.getAuthorName(),
        "authorName must survive the change set round trip");
    Assertions.assertTrue(input.getText().isPresent(), "text must be assigned by the builder");
    Assertions.assertEquals(input.getText(), copy.getText(),
        "text must survive the change set round trip");
    Assertions.assertTrue(input.getCreatedAt().isPresent(),
        "createdAt must be assigned by the builder");
    Assertions.assertEquals(input.getCreatedAt(), copy.getCreatedAt(),
        "createdAt must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the observed issue comment input builder can generate a new identifier")
  void test_observed_issue_comment_create_input_new_uid() {
    ObservedIssueCommentCreateInput input =
        ObservedIssueCommentCreateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        ObservedIssueCommentCreateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the observed issue comment input starts empty and the setters assign values")
  void test_observed_issue_comment_create_input_setters() {
    ObservedIssueCommentCreateInput empty = ObservedIssueCommentCreateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getIssue().isEmpty(), "issue must be empty by default");
    Assertions.assertSame(empty, empty.setIssue(ObservedIssueReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getIssue().isPresent(), "issue must be assigned by the setter");
    Assertions.assertTrue(empty.getAuthor().isEmpty(), "author must be empty by default");
    Assertions.assertSame(empty, empty.setAuthor("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getAuthor().isPresent(), "author must be assigned by the setter");
    Assertions.assertTrue(empty.getAuthorName().isEmpty(), "authorName must be empty by default");
    Assertions.assertSame(empty, empty.setAuthorName("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getAuthorName().isPresent(),
        "authorName must be assigned by the setter");
    Assertions.assertTrue(empty.getText().isEmpty(), "text must be empty by default");
    Assertions.assertSame(empty, empty.setText("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getText().isPresent(), "text must be assigned by the setter");
    Assertions.assertTrue(empty.getCreatedAt().isEmpty(), "createdAt must be empty by default");
    Assertions.assertSame(
        empty, empty.setCreatedAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getCreatedAt().isPresent(),
        "createdAt must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
